TOPIC={'table':'laughter','journey':'nature','home':'simple','books':'reading','conversation':'brief','market':'simple','music':'music','weather':'nature','work':'brief','city':'beauty','garden':'nature','year':'simple','newyear':'simple','valentine':'beauty','lunarnewyear':'laughter','easter':'beauty','earthday':'nature','mothersday':'laughter','fathersday':'laughter','independenceday':'brief','halloween':'halloween','thanksgiving':'laughter','christmas':'christmas'}
photos=json.loads((ROOT/'content/photo-assignments.json').read_text());revisions={}
for p in (D/'data/english-levels').glob('*.json'):
 d=json.loads(p.read_text())
 for level,u in d.items():
  for c in u['cards']:
   if c['type']!='reflection':continue
   if not c.get('quoteAuthor'):revisions[c['id']]=c.copy()
   if not c.get('topicId') and c['id'] in photos:c['visualPhotoScene']=photos[c['id']]['scene']
   tid=c.get('topicId',u.get('topicId','home'));q=BANK[TOPIC.get(tid,'simple')]
   c.update(title=q['text'],meaning=q['meaning'],synonyms=q['synonyms'],example=q['example'],notes=q['note'],quoteAuthor=q['author'],quoteWork=q['work'],quoteYear=q['year'],quoteSourceURL=q['url'],attribution=q['author']+' · '+q['work']+' · Published '+str(q['year']),conversation='A: Which line caught your attention?\nB: “'+q['text'].replace('\n',' ')+'”\nA: How does that connect with the example?\nB: '+q['answer'],exercise='Explain how the example illustrates the quoted idea. Which detail supports your explanation?',answer=q['answer'])
   if level in ['A1','A2']:
    c['conversation']='A: What do you think of this line?\nB: It makes me think about our example.\nA: Which part?\nB: '+q['example']
    c['exercise']='Which action in the example connects with the quotation?'
    c['notes']=q['note']
 p.write_text(json.dumps(d,ensure_ascii=False,separators=(',',':'))+'\n')
backup=ROOT/'content/quote-revisions.json'
old=json.loads(backup.read_text()) if backup.exists() else {};old.update(revisions);backup.write_text(json.dumps(old,separators=(',',':'))+'\n')
(ROOT/'content/verified-quote-bank.json').write_text(json.dumps(BANK,ensure_ascii=False,indent=2)+'\n')
print('Sourced quotes for all stored editions; original reflections retained:',len(old))
